

CREATE TABLE IF NOT EXISTS equip_record (
    id int auto_increment primary key,
    group_code     varchar(50)    null comment '集团编码',
    project_id     varchar(50)    null comment '项目ID',
    system_id      varchar(50)    null comment '系统ID',
    system_code    varchar(50)    null comment '系统编码',
    obj_id         varchar(50)    null comment '设备对象ID',
    change_content json           null comment '指令下发内容',
    exec_status    int default -1 null comment '执行状态: 默认 -1 没有执行;0：执行失败;1：执行成功',
    creator        varchar(50)    null comment '创建人',
    creation_time  varchar(14)    null comment '创建时间',
    modified_time  varchar(50)    null comment '修改时间',
    modifier       varchar(50)    null comment '修改人',
    extend         json           null comment '扩展字段',
    info_code      varchar(32) as (json_unquote(json_extract(`change_content`, _utf8mb4'$.infoCode'))),
    KEY `equip_record_group_code_project_id_system_id_index` (project_id, system_id, group_code) USING BTREE COMMENT '系统ID',
    KEY `equip_record_obj_id_index` (obj_id) USING BTREE COMMENT '对象ID',
    KEY `idx_info_code` (info_code) USING BTREE COMMENT '信息点编码'
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 ROW_FORMAT = DYNAMIC COMMENT = '设备异步指令下发表';


CREATE TABLE IF NOT EXISTS `class_define_config` (
    `class_code` varchar(200) NOT NULL COMMENT '本方自定义的classCode',
    `group_code` varchar(100) DEFAULT NULL COMMENT '集团编码',
    `project_id` varchar(20) DEFAULT NULL COMMENT '项目id',
    `ref_class_code` varchar(255) NOT NULL COMMENT '对应中台的classCode',
    `class_name` varchar(200) DEFAULT NULL COMMENT '设备类名称',
    `ordered` int DEFAULT 0 COMMENT '显示顺序',
    `extend_info` json DEFAULT NULL COMMENT '该设备类业务应用的地方',
    `create_time` datetime DEFAULT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `update_time` datetime DEFAULT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (`class_code`) USING BTREE,
    KEY `nk_define_config_project_id` (`project_id`) USING BTREE COMMENT '项目级别索引'
    ) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 ROW_FORMAT = DYNAMIC COMMENT = '设备类定义表';

CALL Pro_Temp_ColumnWork('rc_info_code_cfg', 'remark_config',
                         '  json DEFAULT NULL COMMENT ''额外所有的配置都在这里配置''',
                         1);
CALL Pro_Temp_ColumnWork('rc_calculate_result', 'extend_info',
                         '  json DEFAULT NULL COMMENT ''扩展信息''',
                         1);






DELETE FROM rc_info_code_cfg;
